(()=>{class i{constructor(e,t){this.DOM={};this.DOM.element=e;this.DOM.acceptBtn=this.DOM.element.querySelector(".lqd-gdpr-accept");this.expires=t;document.body.appendChild(this.DOM.element);this.init();this.eventListeners();this.DOM.element.classList.add("lqd-gdpr-ready")}init(){const e=this.getCookie();if(e.length<1||e[0].split("=")[1]!=="accepted")this.showPopup()}eventListeners(){this.DOM.acceptBtn.addEventListener("click",()=>{this.setCookie.call(this);this.hidePopup.call(this)})}setCookie(){const e=new Date;e.setTime(e.getTime()+this.expires*24*60*60*1000);const t="expires="+e.toUTCString();document.cookie=`lqd-gdpr=accepted; ${t}`}getCookie(){return document.cookie.split(";").filter((e)=>e.trim().split("=")[0]==="lqd-gdpr")}showPopup(){this.DOM.element.classList.add("lqd-gdpr-visible");this.DOM.element.classList.remove("lqd-gdpr-hidden")}hidePopup(){this.DOM.element.classList.add("lqd-gdpr-hidden");this.DOM.element.classList.remove("lqd-gdpr-visible")}}const s=document.querySelector("#lqd-gdpr");if(s)new i(s,365)})();
